"use client"

import { useEffect, useState } from "react"

import "./tybow-motion.css"
import Link from "next/link"

import { buttonVariants } from "@/components/ui/button"
import { ArrowButton } from "@/components/tybow/arrow-button"
import { FlushPhoto, MediaStack } from "@/components/tybow/flush-photo"
import { cn } from "@/lib/utils"

export type ChapterPhoto = { src?: string; alt: string }

export type ChapterProps = {
  id?: string
  eyebrow: string
  line: string
  copy?: string
  photo?: ChapterPhoto
  photos?: ChapterPhoto[]
  cta?: { href: string; label: string }
  secondaryCta?: { href: string; label: string }
  layout?: "stacked" | "split"
  photoSide?: "start" | "end"
  tone?: "paper" | "flush"
}

export function Chapter({
  id,
  eyebrow,
  line,
  copy,
  photo,
  photos,
  cta,
  secondaryCta,
  layout = "stacked",
  photoSide = "end",
  tone = "paper",
}: ChapterProps) {
  const frames = photos?.length ? photos : photo ? [photo] : []
  const flush = tone === "flush" && layout === "stacked" && frames.length > 0
  const [on, setOn] = useState(0)
  const words = line.trim().split(/\s+/)

  useEffect(() => {
    if (!flush || frames.length < 2) return
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    if (reduce) return
    const timer = window.setInterval(() => {
      setOn((i) => (i + 1) % frames.length)
    }, 5600)
    return () => window.clearInterval(timer)
  }, [flush, frames.length])

  const visual = frames.length ? (
    flush ? (
      <MediaStack
        frames={frames}
        on={on}
        slideClassName="tybow-hero-slide"
        className="absolute inset-0 rounded-none"
      />
    ) : (
      <div
        className={cn(
          "relative overflow-hidden",
          layout === "split" ? "aspect-[4/3] rounded-lg" : "aspect-[16/9] rounded-lg",
          layout === "split" && photoSide === "start" && "lg:order-first",
        )}
      >
        <FlushPhoto
          src={frames[0]?.src}
          alt={frames[0]?.alt ?? ""}
          className="absolute inset-0 size-full"
        />
      </div>
    )
  ) : null

  const copyBlock = (
    <div className={cn(flush && "relative z-10 max-w-[min(38rem,100%)]")}>
      <p
        className={cn(
          "text-[0.72rem] font-semibold tracking-[0.2em] uppercase",
          flush ? "text-primary-foreground" : "text-muted-foreground",
        )}
      >
        {eyebrow}
      </p>
      <h2
        className={cn(
          "mt-3 font-display font-medium tracking-[-0.045em] text-balance",
          flush
            ? "text-[length:clamp(4.2rem,13vw,10.5rem)] leading-[0.86] text-primary-foreground"
            : "max-w-[16ch] text-display leading-[1.05] text-foreground",
        )}
      >
        {flush
          ? words.map((word, index) => (
              <span
                key={`${word}-${index}`}
                className="tybow-pull"
                style={{ ["--i" as string]: index }}
              >
                {word}
                {index < words.length - 1 ? "\u00a0" : null}
              </span>
            ))
          : line}
      </h2>
      {copy ? (
        <p
          className={cn(
            "mt-4 max-w-md text-pretty",
            flush
              ? "tybow-pull-late text-primary-foreground/90 [animation-delay:0.42s]"
              : "text-foreground",
          )}
        >
          {copy}
        </p>
      ) : null}
      {cta || secondaryCta ? (
        <div
          className={cn(
            "flex flex-wrap items-center gap-3",
            flush ? "tybow-pull-late mt-8 [animation-delay:0.58s]" : "mt-10",
          )}
        >
          {cta ? (
            flush ? (
              <ArrowButton href={cta.href} variant="cream">
                {cta.label}
              </ArrowButton>
            ) : (
              <Link
                href={cta.href}
                className={buttonVariants({ variant: "default", size: "lg" })}
              >
                {cta.label}
              </Link>
            )
          ) : null}
          {secondaryCta ? (
            flush ? (
              <ArrowButton href={secondaryCta.href} variant="ghost">
                {secondaryCta.label}
              </ArrowButton>
            ) : (
              <Link
                href={secondaryCta.href}
                className={buttonVariants({ variant: "outline", size: "lg" })}
              >
                {secondaryCta.label}
              </Link>
            )
          ) : null}
        </div>
      ) : null}
    </div>
  )

  if (flush) {
    return (
      <section
        id={id}
        className="relative isolate flex min-h-svh flex-col justify-end overflow-hidden bg-foreground"
      >
        {visual}
        <div
          className="pointer-events-none absolute inset-0 bg-[linear-gradient(to_bottom,color-mix(in_oklch,var(--foreground)_78%,transparent)_0%,color-mix(in_oklch,var(--foreground)_42%,transparent)_16%,transparent_38%),linear-gradient(to_right,color-mix(in_oklch,var(--foreground)_72%,transparent)_0%,color-mix(in_oklch,var(--foreground)_14%,transparent)_46%,transparent_62%),linear-gradient(to_top,color-mix(in_oklch,var(--foreground)_86%,transparent)_0%,color-mix(in_oklch,var(--foreground)_52%,transparent)_38%,transparent_66%)]"
          aria-hidden="true"
        />
        <div className="relative z-10 px-[7vw] pt-32 pb-16">{copyBlock}</div>
      </section>
    )
  }

  return (
    <section id={id} className="bg-background">
      <div
        className={cn(
          "mx-auto max-w-[1400px] px-[7vw] py-section",
          layout === "split" &&
            "grid items-start gap-12 lg:grid-cols-2 lg:gap-20",
        )}
      >
        {copyBlock}
        {layout === "stacked" ? <div className="mt-10">{visual}</div> : visual}
      </div>
    </section>
  )
}

import type { ComponentProps, ReactNode } from "react"

import { cn } from "@/lib/utils"

function ArrowIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
      <path
        d="M3 8h10M9 4l4 4-4 4"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="square"
      />
    </svg>
  )
}

export type ArrowButtonProps = {
  variant?: "cream" | "inverse" | "ghost"
  href?: string
  className?: string
  children: ReactNode
} & Omit<ComponentProps<"button">, "className">

export function ArrowButton({
  variant = "cream",
  href,
  className,
  children,
  type = "button",
  ...props
}: ArrowButtonProps) {
  const classes = cn(
    "inline-flex min-h-[3.25rem] items-center gap-3 pr-1.5 pl-5 font-sans text-[0.92rem] font-semibold tracking-[0.04em] uppercase",
    variant === "cream" &&
      "bg-primary-foreground text-foreground shadow-[0_10px_28px_color-mix(in_oklch,var(--foreground)_32%,transparent)] hover:bg-white",
    variant === "inverse" && "bg-primary text-primary-foreground hover:brightness-90",
    variant === "ghost" &&
      "min-h-[3.25rem] border-[1.5px] border-primary-foreground bg-foreground/60 px-5 text-primary-foreground hover:border-white hover:bg-foreground/80",
    className,
  )

  const iconWrap =
    variant === "ghost" ? null : (
      <span
        className={cn(
          "grid size-9 place-items-center",
          variant === "cream" && "bg-primary text-primary-foreground",
          variant === "inverse" && "bg-primary-foreground text-primary",
        )}
      >
        <ArrowIcon />
      </span>
    )

  const inner = (
    <>
      {children}
      {iconWrap}
    </>
  )

  if (href) {
    return (
      <a href={href} className={classes}>
        {inner}
      </a>
    )
  }

  return (
    <button type={type} className={classes} {...props}>
      {inner}
    </button>
  )
}

import { cn } from "@/lib/utils"

export type FlushPhotoProps = {
  src?: string
  alt: string
  label?: string
  fit?: "cover" | "contain"
  className?: string
}

export type MediaFrame = { src?: string; alt: string }

export function MediaStack({
  frames,
  on,
  slideClassName,
  className,
  objectPosition,
}: {
  frames: MediaFrame[]
  on: number
  slideClassName: string
  className?: string
  objectPosition?: string
}) {
  return (
    <div className={cn("relative overflow-hidden bg-muted", className)}>
      {frames.map((frame, index) =>
        frame.src ? (
          // Parent owns crop. Animation classes must land on the img.
          // eslint-disable-next-line @next/next/no-img-element
          <img
            key={`${frame.src}-${index}`}
            src={frame.src}
            alt={index === on ? frame.alt : ""}
            decoding="async"
            className={cn(slideClassName, index === on && "is-on")}
            style={objectPosition ? { objectPosition } : undefined}
          />
        ) : (
          <div
            key={`${frame.alt}-${index}`}
            className={cn(
              slideClassName,
              index === on && "is-on",
              "flex items-center justify-center bg-muted",
            )}
            role="img"
            aria-label={frame.alt}
          />
        ),
      )}
    </div>
  )
}

export function FlushPhoto({
  src,
  alt,
  label = "replace with client photo",
  fit = "cover",
  className,
}: FlushPhotoProps) {
  return (
    <div className={cn("relative overflow-hidden bg-muted", className)}>
      {src ? (
        // Parent owns crop and radius. No inner mat.
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={src}
          alt={alt}
          className={cn(
            "absolute inset-0 size-full",
            fit === "contain" ? "object-contain" : "object-cover",
          )}
        />
      ) : (
        <div
          className="absolute inset-0 flex items-center justify-center bg-muted px-6 text-center"
          role="img"
          aria-label={alt}
        >
          <p className="text-sm text-muted-foreground">{label}</p>
        </div>
      )}
    </div>
  )
}

/* Motion ported from The Pines: wh-pines.css + wh-pe-brand.css.
   Token-only. Values (timings, easings, travel) stay literal. */

@keyframes tybow-pull {
  to {
    transform: none;
    opacity: 1;
  }
}

.tybow-pull {
  display: inline-block;
  transform: translateY(0.42em);
  opacity: 0;
  animation: tybow-pull 0.72s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  animation-delay: calc(var(--i, 0) * 90ms + 80ms);
}

.tybow-pull-late {
  transform: translateY(0.8rem);
  opacity: 0;
  animation: tybow-pull 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Ken Burns lives on the IMG, not a wrapper. */
.tybow-hero-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  object-position: 50% 52%;
  opacity: 0;
  transform: scale(1.02);
  transition:
    opacity 1.1s cubic-bezier(0.22, 1, 0.36, 1),
    transform 7s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}

.tybow-hero-slide.is-on {
  opacity: 1;
  transform: scale(1);
}

.tybow-look-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-look-slide.is-on {
  opacity: 1;
}

.tybow-overview-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.55s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-overview-slide.is-on {
  opacity: 1;
  z-index: 1;
}

.tybow-gallery {
  display: flex;
  flex-direction: row;
  gap: 1px;
  width: 100%;
  height: min(56vh, 32rem);
  min-height: 22rem;
  overflow: hidden;
  background: var(--foreground);
}

.tybow-gallery-item {
  position: relative;
  overflow: hidden;
  flex: 0.5 1 2.55rem;
  min-width: 2.45rem;
  height: 100%;
  padding: 0;
  border: 0;
  background: var(--foreground);
  cursor: pointer;
  text-align: left;
  line-height: 0;
  transition: flex-grow 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-gallery-item.is-active {
  flex-grow: 16;
}

.tybow-gallery-item img,
.tybow-gallery-item .tybow-gallery-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 48%;
}

.tybow-gallery-item::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    to right,
    color-mix(in oklch, var(--foreground) 88%, transparent) 0%,
    color-mix(in oklch, var(--foreground) 62%, transparent) 55%,
    color-mix(in oklch, var(--foreground) 28%, transparent) 100%
  );
  opacity: 1;
  transition: opacity 0.3s ease;
}

.tybow-gallery-item.is-active::after {
  opacity: 0;
}

.tybow-gallery-spine {
  position: absolute;
  inset: 0 auto 0 0;
  z-index: 1;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  padding: 1.05rem 0.55rem;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--primary-foreground);
  text-shadow: 0 1px 12px color-mix(in oklch, var(--foreground) 70%, transparent);
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.25s ease;
}

.tybow-gallery-item.is-active .tybow-gallery-spine {
  opacity: 0;
}

.tybow-gallery-cap {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  padding: 2.6rem 1.2rem 1.05rem;
  background: linear-gradient(
    to top,
    color-mix(in oklch, var(--foreground) 70%, transparent),
    transparent
  );
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--primary-foreground);
  pointer-events: none;
  opacity: 0;
  transform: translateY(0.5rem);
  transition:
    opacity 0.3s ease,
    transform 0.3s ease;
}

.tybow-gallery-item.is-active .tybow-gallery-cap {
  opacity: 1;
  transform: none;
}

.tybow-deck-card-body,
.tybow-deck-card::after {
  transition:
    opacity 420ms ease,
    transform 420ms ease;
}

.tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
  opacity: 0.55;
  transform: translateY(10px);
}

.tybow-spec-line {
  --pin-line-delay: 0ms;
}

.tybow-spec-line::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 1px;
  background: var(--border);
}

@media (prefers-reduced-motion: no-preference) {
  .tybow-spec .tybow-spec-line::after {
    transform: scaleX(0);
    transform-origin: left center;
    transition: transform 620ms cubic-bezier(0.23, 1, 0.32, 1)
      var(--pin-line-delay, 0ms);
  }

  .tybow-spec .tybow-spec-tick {
    opacity: 0;
    transform: translateX(-5px);
    transition:
      opacity 420ms cubic-bezier(0.23, 1, 0.32, 1) var(--pin-line-delay, 0ms),
      transform 420ms cubic-bezier(0.23, 1, 0.32, 1) var(--pin-line-delay, 0ms);
  }

  .tybow-spec.is-inview .tybow-spec-line::after {
    transform: scaleX(1);
  }

  .tybow-spec.is-inview .tybow-spec-tick {
    opacity: 1;
    transform: none;
  }

  .tybow-spec-line:nth-child(1) {
    --pin-line-delay: 300ms;
  }
  .tybow-spec-line:nth-child(2) {
    --pin-line-delay: 375ms;
  }
  .tybow-spec-line:nth-child(3) {
    --pin-line-delay: 450ms;
  }
  .tybow-spec-line:nth-child(4) {
    --pin-line-delay: 525ms;
  }
  .tybow-spec-line:nth-child(5) {
    --pin-line-delay: 600ms;
  }
  .tybow-spec-line:nth-child(6) {
    --pin-line-delay: 675ms;
  }
}

@media (max-width: 800px) {
  .tybow-gallery {
    height: auto;
    min-height: 0;
    flex-direction: column;
  }

  .tybow-gallery-item {
    flex: 0 0 2.65rem;
    width: 100%;
    min-width: 0;
    height: 2.65rem;
    transition:
      height 0.4s cubic-bezier(0.22, 1, 0.36, 1),
      flex-basis 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  }

  .tybow-gallery-item.is-active {
    flex: 0 0 22rem;
    height: 22rem;
  }

  .tybow-gallery-item::after {
    background: linear-gradient(
      to top,
      color-mix(in oklch, var(--foreground) 88%, transparent) 0%,
      color-mix(in oklch, var(--foreground) 45%, transparent) 70%,
      transparent 100%
    );
  }

  .tybow-gallery-spine {
    writing-mode: horizontal-tb;
    transform: none;
    inset: auto auto 0.7rem 0.9rem;
    padding: 0;
    font-size: 0.78rem;
    letter-spacing: 0.16em;
  }
}

@media (max-width: 959px) {
  .tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tybow-pull,
  .tybow-pull-late {
    animation: none;
    opacity: 1;
    transform: none;
  }

  .tybow-hero-slide,
  .tybow-hero-slide.is-on,
  .tybow-look-slide,
  .tybow-overview-slide,
  .tybow-gallery-item,
  .tybow-gallery-item::after,
  .tybow-gallery-spine,
  .tybow-gallery-cap,
  .tybow-deck-card-body,
  .tybow-deck-card::after {
    transition: none;
    transform: none;
  }

  .tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
    opacity: 1;
    transform: none;
  }
}
